// Globals shared between the classic scripts of the host page and the gate.
// site.js is generated by scripts/build-site.mjs; the rest is set by our scripts.
export {};

declare global {
  /** Deployment origins, from IDE_URL / GATE_URL at build time (empty when built without them). */
  var SITE_CONFIG: { ideUrl?: string; gateUrl?: string } | undefined;
  /** Where the network gate is served (the dist/ root on the gate's origin). */
  var GATE_URL: string | undefined;

  interface Window {
    /** BroadcastChannel name of this tab's gate relay (set by gate-relay.ts, read by boot.ts). */
    __vmGateChannel?: string;
    /** Workbench construction options (IWorkbenchConstructionOptions), set by boot.ts. */
    product: Record<string, unknown>;
    /** URL of dist/vscode, without a trailing slash (set by boot.ts, read by amd-config.ts). */
    __vscodeBase: string;
    /** Trusted Types, where the browser supports it. */
    trustedTypes?: { createPolicy(name: string, rules: { createScriptURL(value: string): string }): unknown };
  }

  /** Module name → path, defined by vscode/out/vs/webPackagePaths.js. */
  var webPackagePaths: Record<string, string>;

  /** Code-OSS's AMD loader (vscode/out/vs/loader.js). */
  var require: { config(options: Record<string, unknown>): void };
}
